import { useEffect, useState } from "react";

interface Cache<T> {
  get(): T;
  subscribe(listener: (value: T) => void): () => void;
}

export function useCachedValue<T>(cache: Cache<T>): T {
  const [value, setValue] = useState(() => cache.get());

  useEffect(() => cache.subscribe(setValue), [cache]);

  return value;
}

