interface DehydratedState {
  readonly mutations?: readonly unknown[];
  readonly queries?: readonly unknown[];
}

export function hydratePartialState(state: DehydratedState): number {
  let hydrated = 0;
  state.mutations?.forEach(() => {
    hydrated += 1;
  });
  state.queries?.forEach(() => {
    hydrated += 1;
  });
  return hydrated;
}
